import * as T from './vendor/three.module.js';
const cache={};
function resources(){if(cache.ready)return cache;cache.ready=true;
const cloth=document.createElement('canvas');cloth.width=cloth.height=256;let c=cloth.getContext('2d');c.fillStyle='#aaa';c.fillRect(0,0,256,256);for(let i=0;i<256;i+=2){c.fillStyle=i%4?'#b6b6b6':'#969696';c.fillRect(i,0,1,256);c.fillStyle='#8888';c.fillRect(0,i,256,1)}let bump=new T.CanvasTexture(cloth);bump.wrapS=bump.wrapT=T.RepeatWrapping;bump.repeat.set(3,3);
const skinCanvas=document.createElement('canvas');skinCanvas.width=skinCanvas.height=128;const sc=skinCanvas.getContext('2d');sc.fillStyle='#a86a42';sc.fillRect(0,0,128,128);for(let i=0;i<340;i++){const v=(i*97)%128,w=(i*53)%128;sc.fillStyle=i%3?'rgba(76,38,20,.07)':'rgba(255,202,154,.055)';sc.fillRect(v,w,1+(i%3),1)}let skinBump=new T.CanvasTexture(skinCanvas);skinBump.wrapS=skinBump.wrapT=T.RepeatWrapping;skinBump.repeat.set(2,2);
cache.tan=new T.MeshStandardMaterial({color:'#9a7048',roughness:.86,bumpMap:bump,bumpScale:.009});cache.seam=new T.MeshStandardMaterial({color:'#594330',roughness:1});cache.white=new T.MeshStandardMaterial({color:'#e5e3da',roughness:.84,bumpMap:bump,bumpScale:.004});cache.sole=new T.MeshStandardMaterial({color:'#bfc4c4',roughness:.76});cache.skin=new T.MeshPhysicalMaterial({color:'#925b38',roughness:.46,clearcoat:.03,bumpMap:skinBump,bumpScale:.004});cache.beard=new T.MeshStandardMaterial({color:'#171817',roughness:.86});cache.hair=new T.MeshStandardMaterial({color:'#161514',roughness:.9});cache.gold=new T.MeshStandardMaterial({color:'#d2ad59',metalness:.88,roughness:.2});cache.eye=new T.MeshStandardMaterial({color:'#e6dacb',roughness:.34});cache.iris=new T.MeshStandardMaterial({color:'#241a13',roughness:.24});cache.lip=new T.MeshStandardMaterial({color:'#623b2a',roughness:.65});return cache}
export function makeCharacter(scene,{detail=false}={}){
const r=resources(),root=new T.Group();scene.add(root);const body=new T.Group();root.add(body);
function add(geo,mat,x,y,z,parent=body){let m=new T.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function ellipsoid(rx,ry,rz,mat,x,y,z,parent=body){let m=add(new T.SphereGeometry(1,detail?24:12,detail?16:8),mat,x,y,z,parent);m.scale.set(rx,ry,rz);return m}
function capsule(radius,len,mat,x,y,z,parent=body){return add(new T.CapsuleGeometry(radius,len,6,detail?16:8),mat,x,y,z,parent)}
function tapered(a,b,len,mat,x,y,z,parent=body){return add(new T.CylinderGeometry(a,b,len,detail?12:8),mat,x,y,z,parent)}
function bar(a,b,width,mat,parent=body){let p=new T.Vector3(...a),q=new T.Vector3(...b),d=q.clone().sub(p);let m=add(new T.CylinderGeometry(width,width,d.length(),8),mat,0,0,0,parent);m.position.copy(p.add(q).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());return m}
// Tailored torso: waist, chest and sloped shoulders, rather than a cylinder.
const profile=[[.87,.19],[.95,.22],[1.08,.25],[1.25,.285],[1.37,.30],[1.43,.255],[1.47,.16]];let torso=add(new T.LatheGeometry(profile.map(([y,x])=>new T.Vector2(x,y)),detail?40:24),r.tan,0,0,0);torso.scale.z=.67;
let hips=add(new T.CylinderGeometry(.21,.205,.18,24),r.tan,0,.86,0);hips.scale.z=.70;ellipsoid(.16,.29,.035,r.white,0,1.19,.164);
// Lower jacket overlap and rear yoke hide mechanical-looking hip and shoulder gaps.
ellipsoid(.235,.075,.145,r.tan,0,.92,-.015);
for(let side of [-1,1]){bar([side*.105,.94,.171],[side*.14,1.38,.171],.016,r.seam);let collar=add(new T.BoxGeometry(.10,.15,.018),r.tan,side*.11,1.42,.157);collar.rotation.z=side*.45;if(detail){let pocket=add(new T.BoxGeometry(.12,.15,.018),r.tan,side*.18,1.07,.153);pocket.rotation.z=-side*.12;bar([side*.12,1.15,.174],[side*.23,1.12,.16],.004,r.seam);bar([side*.20,.96,-.12],[side*.24,1.33,-.15],.003,r.seam)}}
bar([-.20,.94,-.11],[.20,.94,-.11],.009,r.seam);
capsule(.069,.12,r.skin,0,1.50,0);const head=new T.Group();head.position.set(0,1.70,0);body.add(head);
// Layered cranium, jaw and facial planes give the close camera a human silhouette.
ellipsoid(.145,.185,.145,r.skin,0,.01,0,head);ellipsoid(.132,.102,.132,r.skin,0,-.085,.025,head);ellipsoid(.121,.071,.136,r.beard,0,-.105,.042,head);ellipsoid(.075,.052,.052,r.skin,0,-.015,.135,head);ellipsoid(.025,.039,.034,r.skin,0,.018,.174,head);ellipsoid(.048,.012,.016,r.lip,0,-.058,.166,head);
for(let side of [-1,1]){ellipsoid(.026,.047,.022,r.skin,side*.145,-.003,.002,head);ellipsoid(.044,.024,.017,r.skin,side*.065,.021,.132,head);ellipsoid(.034,.016,.012,r.eye,side*.059,.046,.148,head);ellipsoid(.012,.013,.009,r.iris,side*.059,.046,.16,head);let brow=add(new T.BoxGeometry(.067,.016,.017),r.beard,side*.06,.079,.145,head);brow.rotation.z=side*.10;ellipsoid(.011,.011,.007,r.gold,side*.165,-.029,.012,head);if(detail){ellipsoid(.048,.016,.012,r.skin,side*.06,.069,.144,head);bar([side*.034,.030,.16],[side*.09,.030,.147],.003,r.skin,head)}}
let chain=add(new T.TorusGeometry(.118,.006,6,40,Math.PI),r.gold,0,1.39,.185);chain.rotation.z=Math.PI;add(new T.BoxGeometry(.021,.032,.008),r.gold,0,1.27,.198);
const arms=[],legs=[];for(let side of [-1,1]){const upper=new T.Group();upper.position.set(side*.283,1.36,0);upper.rotation.z=side*.075;body.add(upper);ellipsoid(.108,.135,.115,r.tan,0,-.035,0,upper);tapered(.09,.078,.25,r.tan,0,-.19,0,upper);const lower=new T.Group();lower.position.set(0,-.365,0);upper.add(lower);ellipsoid(.079,.075,.082,r.tan,0,.0,0,lower);tapered(.078,.058,.225,r.tan,0,-.15,.004,lower);capsule(.061,.014,r.tan,0,-.275,0,lower);ellipsoid(.053,.081,.036,r.skin,0,-.36,.008,lower);if(detail){for(let f=0;f<4;f++){let finger=capsule(.008,.05,r.skin,-.03+f*.02,-.41,.016,lower);finger.rotation.x=-.12}let thumb=capsule(.012,.044,r.skin,side*.05,-.35,.02,lower);thumb.rotation.z=-side*.4}arms.push({upper,lower});
const thigh=new T.Group();thigh.position.set(side*.118,.88,0);root.add(thigh);ellipsoid(.108,.13,.105,r.tan,0,-.08,0,thigh);tapered(.112,.097,.30,r.tan,0,-.23,0,thigh);const knee=new T.Group();knee.position.set(0,-.46,0);thigh.add(knee);ellipsoid(.094,.087,.094,r.tan,0,.005,0,knee);tapered(.091,.069,.26,r.tan,0,-.16,.005,knee);capsule(.066,.016,r.tan,0,-.32,0,knee);const foot=new T.Group();foot.position.set(0,-.39,.055);knee.add(foot);ellipsoid(.104,.071,.19,r.white,0,-.005,.035,foot);let sole=add(new T.BoxGeometry(.20,.024,.33),r.sole,0,-.06,.045,foot);if(detail){for(let j=0;j<4;j++)bar([-.06,.042,-.015+j*.026],[.06,.042,-.015+j*.026],.004,r.sole,foot);bar([side*.104,-.01,-.04],[side*.104,.01,.11],.005,r.sole,foot);bar([side*.086,-.15,-.005],[side*.086,-.31,-.005],.003,r.seam,knee)}legs.push({thigh,knee,foot});}
const shadow=add(new T.CircleGeometry(.34,32),new T.MeshBasicMaterial({color:'#15201a',transparent:true,opacity:.13,depthWrite:false}),0,.077,0,root);shadow.rotation.x=-Math.PI/2;
let gait=0,previous=0,blend=0;return{root,update(time,moving,running){let dt=Math.min(.05,Math.max(.001,time-previous));previous=time;blend=T.MathUtils.damp(blend,moving?1:0,9,dt);gait+=dt*(running?11:7);let a=Math.sin(gait),b=Math.sin(gait+Math.PI),amp=running?.78:.42;for(let i=0;i<2;i++){let s=i?b:a;legs[i].thigh.rotation.x=s*amp*blend;legs[i].knee.rotation.x=-Math.max(0,-s)*(running?1.15:.65)*blend;legs[i].foot.rotation.x=-legs[i].thigh.rotation.x*.3-legs[i].knee.rotation.x*.45;arms[i].upper.rotation.x=-s*(running?.72:.35)*blend;arms[i].lower.rotation.x=-(.12+(running?.8:.1)*blend)}body.position.y=Math.abs(Math.sin(gait*2))*.022*blend;body.rotation.z=a*.025*blend;body.rotation.y=a*.045*blend;head.rotation.y=-a*.025*blend;body.rotation.x=running?.10*blend:0}};
}
